<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\Report; use App\Models\Resource; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage;
class AdminResourceController extends Controller { public function reports(){return view('admin.reports.index',['reports'=>Report::with(['user','resource.user'])->where('status',Report::STATUS_OPEN)->latest()->paginate(20)]);} public function keep(Report $report){$report->update(['status'=>Report::STATUS_DISMISSED]);return back()->with('status','Report dismissed; resource remains published.');} public function remove(Report $report){$resource=$report->resource;if($resource){Storage::disk('public')->delete($resource->file_path);$resource->update(['status'=>'removed']);}$report->update(['status'=>Report::STATUS_RESOLVED]);return back()->with('status','Resource removed and report resolved.');} public function warn(Request $request,Report $report){$report->update(['status'=>Report::STATUS_RESOLVED]);return back()->with('status','Warning recorded for '.$report->resource?->user?->email.'. Configure mail delivery to send external warnings.');} }
